use vstd::prelude::*;

verus! {

    // A pure, mathematical predicate saying
    //   a and b have the same length, and
    //   for every index i in 0..a.len(), a[i] > b[i].
    spec fn all_gt(a: Seq<i32>, b: Seq<i32>) -> bool
        requires
            a.len() == b.len(),
        decreases
            a.len(),
    {
        forall |i: nat|
            i < a.len() ==>
            a[i] > b[i]
    }

    // Returns `true` exactly when arr1[i] > arr2[i] for all 0 <= i < arr1.len().
    // By convention, empty arrays satisfy the predicate.
    fn is_smaller(arr1: &Vec<i32>, arr2: &Vec<i32>) -> (result: bool)
        requires
            arr1.len() == arr2.len(),
        ensures
            // We compare the *views* (the @‐notation) of the Vecs as Seq<i32>.
            result == all_gt(arr1@, arr2@),
    {
        let n: usize = arr1.len();
        let mut i: usize = 0;
        while i < n
            invariant
                // `i` always stays in [0..=n]
                i <= n,
                // for all j < i, we already have arr1[j] > arr2[j]
                forall |j: nat| j < i ==> arr1@[j] > arr2@[j],
            decreases
                n - i,
        {
            // as soon as one pair fails the test, return false
            if !(arr1[i] > arr2[i]) {
                return false;
            }
            i += 1;
        }
        // if we never saw a failure, return true
        true
    }

} // end verus! 

